    if len(str_n) <= 3:
        return str_n
    else:
        # Insert commas every three characters from the right
        return ','.join(str_n[i:i+3] for i in range(len(str_n)-2, -1, -3))

def inr_format(n):
    str_n = str(n)
    len_n = len(str_n)
    chunks = []
    for i in range(len_n - 3, -1, -3):
        chunks.append(str_n[i:i+3])
        if i != 0:
            chunks.append(',')
    formatted_str = ' '.join(chunks)
    return formatted_str

